#include "study_support.h"
#include <cuda_runtime.h>
#include "../deredundancy-cuda/kernels.cu"
void ck(cudaError_t e){if(e!=cudaSuccess)throw std::runtime_error(cudaGetErrorString(e));}
template<class T>struct Buf{T*base;T*data;size_t n;T sentinel;Buf(size_t nn,T s):n(nn),sentinel(s){ck(cudaMalloc(&base,(n+16)*sizeof(T)));data=base+8;std::vector<T>v(n+16,s);std::fill(v.begin()+8,v.end()-8,T(0));ck(cudaMemcpy(base,v.data(),v.size()*sizeof(T),cudaMemcpyHostToDevice));}~Buf(){cudaFree(base);}std::vector<T>get(){std::vector<T>v(n);ck(cudaMemcpy(v.data(),data,n*sizeof(T),cudaMemcpyDeviceToHost));return v;}void zero(){ck(cudaMemset(data,0,n*sizeof(T)));}void append(std::vector<int64_t>&v){for(T x:get())v.push_back(x);}void guards(std::vector<int64_t>&v){std::vector<T>g(8);ck(cudaMemcpy(g.data(),base,8*sizeof(T),cudaMemcpyDeviceToHost));for(T x:g)v.push_back(x);ck(cudaMemcpy(g.data(),data+n,8*sizeof(T),cudaMemcpyDeviceToHost));for(T x:g)v.push_back(x);}};
struct Device{Case c;Buf<int>lengths,gaps,magic,cutoff,cluster,representative;Buf<long>offsets,words;Buf<uint8_t>reads;Buf<unsigned>compressed;Buf<unsigned short>index,orders,table;std::vector<unsigned short>hostindex;std::vector<long>hostoffsets,hostwords;std::vector<int>hostcluster;int r=-1;
Device(const Case&cc):c(cc),lengths(c.n,-777),gaps(c.n,-777),magic(c.n*4,-777),cutoff(c.n,-777),cluster(c.n,-777),representative(1,-777),offsets(c.n+1,-777),words(c.n,-777),reads(c.total,165),compressed(c.np,0xdeadbeef),index(c.total,65534),orders(c.total,65534),table(65536,65534),hostindex(c.total),hostoffsets(c.n+1),hostwords(c.n),hostcluster(c.n){reset();}
void reset(){ck(cudaMemcpy(lengths.data,c.lengths.data(),c.n*4,cudaMemcpyHostToDevice));ck(cudaMemcpy(offsets.data,c.offsets.data(),(c.n+1)*8,cudaMemcpyHostToDevice));ck(cudaMemcpy(reads.data,c.raw.data(),c.total,cudaMemcpyHostToDevice));gaps.zero();magic.zero();cutoff.zero();words.zero();compressed.zero();index.zero();orders.zero();table.zero();ck(cudaMemset(cluster.data,255,c.n*4));ck(cudaMemset(representative.data,255,4));r=-1;}
void prefix(std::vector<int64_t>&v){lengths.append(v);offsets.append(v);reads.append(v);compressed.append(v);gaps.append(v);index.append(v);orders.append(v);words.append(v);magic.append(v);cutoff.append(v);cluster.append(v);table.append(v);representative.append(v);}
void pipeline(bool tracing,std::vector<int64_t>&rawindex,std::vector<int64_t>&trace){ck(cudaMemcpy(lengths.data,c.lengths.data(),c.n*4,cudaMemcpyHostToDevice));ck(cudaMemcpy(offsets.data,c.offsets.data(),(c.n+1)*8,cudaMemcpyHostToDevice));ck(cudaMemcpy(reads.data,c.raw.data(),c.total,cudaMemcpyHostToDevice));kernel_baseToNumber<<<128,128>>>((char*)reads.data,c.total);int blocks=(c.n+127)/128;kernel_compressData<<<blocks,128>>>(lengths.data,offsets.data,(char*)reads.data,compressed.data,gaps.data,c.n);
switch(c.k){case 4:kernel_createIndex4<<<blocks,128>>>((char*)reads.data,lengths.data,offsets.data,index.data,orders.data,words.data,magic.data,c.n);break;case 5:kernel_createIndex5<<<blocks,128>>>((char*)reads.data,lengths.data,offsets.data,index.data,orders.data,words.data,magic.data,c.n);break;case 6:kernel_createIndex6<<<blocks,128>>>((char*)reads.data,lengths.data,offsets.data,index.data,orders.data,words.data,magic.data,c.n);break;case 7:kernel_createIndex7<<<blocks,128>>>((char*)reads.data,lengths.data,offsets.data,index.data,orders.data,words.data,magic.data,c.n);break;default:throw std::runtime_error("k");}
kernel_createCutoff<<<blocks,128>>>(c.threshold,c.k,lengths.data,words.data,cutoff.data,c.n);ck(cudaMemcpy(hostindex.data(),index.data,c.total*2,cudaMemcpyDeviceToHost));ck(cudaMemcpy(hostoffsets.data(),offsets.data,(c.n+1)*8,cudaMemcpyDeviceToHost));ck(cudaMemcpy(hostwords.data(),words.data,c.n*8,cudaMemcpyDeviceToHost));if(tracing)for(auto x:hostindex)rawindex.push_back(x);
for(uint32_t i=0;i<c.n;i++){long start=hostoffsets[i];
#ifndef DERED_ORIGINAL_PREFIX
long dst=start;for(long j=start;j<start+c.lengths[i];j++)if(hostindex[j]!=65535)hostindex[dst++]=hostindex[j];if(dst-start!=hostwords[i])throw std::runtime_error("validwordcount");
#endif
std::sort(hostindex.begin()+start,hostindex.begin()+start+hostwords[i]);}
ck(cudaMemcpy(index.data,hostindex.data(),c.total*2,cudaMemcpyHostToDevice));kernel_mergeIndex<<<blocks,128>>>(offsets.data,index.data,orders.data,words.data,c.n);
while(r<(int)c.n){ck(cudaMemcpy(representative.data,&r,4,cudaMemcpyHostToDevice));kernel_updateRepresentative<<<1,1>>>(cluster.data,representative.data,c.n);ck(cudaMemcpy(&r,representative.data,4,cudaMemcpyDeviceToHost));if(tracing){trace.push_back(r);cluster.append(trace);}if(r>=(int)c.n-1)break;kernel_makeTable<<<128,128>>>(offsets.data,index.data,orders.data,words.data,table.data,r);if(tracing)table.append(trace);kernel_magic<<<blocks,128>>>(c.threshold,lengths.data,magic.data,cluster.data,r,c.n);if(tracing)cluster.append(trace);kernel_filter<<<c.n,128>>>(c.threshold,c.k,lengths.data,offsets.data,index.data,orders.data,words.data,cutoff.data,cluster.data,table.data,c.n);if(tracing)cluster.append(trace);kernel_align<<<blocks,128>>>(c.threshold,lengths.data,offsets.data,compressed.data,gaps.data,r,cluster.data,c.n);if(tracing)cluster.append(trace);kernel_cleanTable<<<128,128>>>(offsets.data,index.data,orders.data,words.data,table.data,r);if(tracing)table.append(trace);}
ck(cudaMemcpy(hostcluster.data(),cluster.data,c.n*4,cudaMemcpyDeviceToHost));ck(cudaDeviceSynchronize());}
std::vector<int64_t>final(){std::vector<int64_t>v;reads.append(v);compressed.append(v);gaps.append(v);index.append(v);orders.append(v);words.append(v);magic.append(v);cutoff.append(v);cluster.append(v);table.append(v);representative.append(v);return v;}
void guards(std::vector<int64_t>&v){lengths.guards(v);offsets.guards(v);reads.guards(v);compressed.guards(v);gaps.guards(v);index.guards(v);orders.guards(v);words.guards(v);magic.guards(v);cutoff.guards(v);cluster.guards(v);table.guards(v);representative.guards(v);}
std::string fasta(){std::string text;for(uint32_t i=0;i<c.n;i++)if(hostcluster[i]==(int)i)text+=">read_"+std::to_string(i)+"\n"+std::string((char*)c.raw.data()+c.offsets[i],c.lengths[i])+"\n";return text;}};
static std::pair<double,std::vector<int64_t>> run(){auto cs=cases();std::vector<int64_t>prefix,out;double seconds=0;for(auto&c:cs){Device d(c);d.prefix(prefix);std::vector<int64_t>unused,trace,rawindex;ck(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();d.pipeline(false,unused,unused);seconds+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();auto timed=d.final();out.insert(out.end(),timed.begin(),timed.end());auto text=d.fasta();out.push_back(text.size());for(uint8_t ch:text)out.push_back(ch);d.reset();d.pipeline(true,rawindex,trace);if(d.final()!=timed)throw std::runtime_error("untimedreplaychangedfinal");out.insert(out.end(),rawindex.begin(),rawindex.end());out.push_back(trace.size());out.insert(out.end(),trace.begin(),trace.end());if(d.lengths.get()!=c.lengths||d.offsets.get()!=c.offsets)throw std::runtime_error("readonlyinput");d.guards(out);}prefix.insert(prefix.end(),out.begin(),out.end());return {seconds,prefix};}
int main(){try{run();for(int trial=1;trial<=5;trial++){auto v=run();std::string path="trial"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)v.second.data(),v.second.size()*8);f.close();check(v.second,cases());std::cout<<std::setprecision(17)<<"\nSTUDY_TRIAL {\"trial\":"<<trial<<",\"time_seconds\":"<<v.first<<",\"correct\":true,\"checked_values\":"<<v.second.size()<<",\"max_abs_error\":0,\"max_rel_error\":null,\"timing_region\":\"preallocated_full_pipeline_transfers_hostsort_repclustering_sum4cases\",\"jit_excluded\":true,\"internal_repeats\":1,\"output_artifact\":{\"path\":\""<<path<<"\",\"dtype\":\"int64\",\"count\":"<<v.second.size()<<",\"byte_order\":\"little\"}}\n";}}catch(std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
